#!/usr/bin/env python3
"""All-cell radial/scatter comparison after one actual old-FD vector solve."""
import argparse,hashlib,json,os,tempfile
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('evidence',type=Path);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output;out.mkdir(exist_ok=False);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();mp=a.evidence/'manifest.json';bp=a.evidence/'probe.csv.beta.csv';m=json.loads(mp.read_text());d=np.genfromtxt(bp,delimiter=',',names=True);assert len(d)==47088 and np.array_equal(d['point'],np.arange(47088));assert all(np.isfinite(d[name]).all() for name in d.dtype.names);assert m['norms']['candidate_actual_initial_elliptic_shift_solved'] and not m['norms']['known_independent_radial_shift_shared_for_validation'];w=d['weight'];error=d['radial_beta']-d['reference_radial_beta'];_,groups=np.unique(np.round(d['r'],14),return_inverse=True);profiles=[]
for group in range(groups.max()+1):
 use=groups==group;weight=w[use];weight=weight/weight.sum();mean=float(sum(weight*error[use]));profiles.append({'radius':float(sum(weight*d['r'][use])),'count':int(sum(use)),'radial_error_mean':mean,'angular_scatter':float(np.sqrt(sum(weight*(error[use]-mean)**2))),'radius_span':float(np.ptp(d['r'][use])),'tangential_RMS':float(np.sqrt(sum(weight*d['tangential_norm'][use]**2)))})
assert sum(row['count'] for row in profiles)==len(d);assert max(row['radius_span'] for row in profiles)<1.1e-14
vector_rms=float(np.sqrt(sum(w*d['vector_error']**2)/sum(w)));assert abs(vector_rms-m['shift_solve']['vector_beta_error']['RMS'])<1e-13;np.savez_compressed(out/'actual-stage-all-cell-beta.npz',fields=np.array(d.dtype.names),data=np.stack([d[name] for name in d.dtype.names],axis=1));summary={'scope':'One actual frozenv15 original-vector solve, not evolution/coupled acceptance','solve':m['shift_solve'],'all_24_source_norms':m['norms'],'radial_error_angular_scatter':profiles,'all_cells_retained':len(d),'radius_grouping_decimal_places':14,'maximum_radius_span':max(row['radius_span'] for row in profiles),'scientific_acceptance':False,'production_adopted':False,'input_sha256':{str(mp):sha(mp),str(bp):sha(bp)},'script_sha256':sha(Path(__file__))}
with tempfile.TemporaryDirectory(dir=out,prefix='plot-cache-') as cache:
 os.environ['MPLCONFIGDIR']=cache;os.environ['XDG_CACHE_HOME']=cache
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,3,figsize=(15,4),layout='constrained');axes[0].scatter(d['r'],d['radial_beta'],s=1,alpha=.2,label='actual elliptic solve');axes[0].scatter(d['r'],d['reference_radial_beta'],s=1,alpha=.2,label='independent1D');axes[0].set(xlabel='r',ylabel='radial beta',title='All47088 cells; no radial projection');axes[0].legend(fontsize=7)
 axes[1].scatter(d['r'],abs(error),s=1,alpha=.2,label='radial error');axes[1].scatter(d['r'],d['tangential_norm'],s=1,alpha=.2,label='tangential beta');axes[1].set(xlabel='r',ylabel='absolute error',yscale='log',xscale='log',title='Angular scatter retained');axes[1].legend(fontsize=7)
 channels=['error_chi_rate','error_Khat_rate','error_Theta_rate','error_alpha_rate','error_A_xx','error_Lambda_x'];norms=m['norms']['regions']['all']['global_free_background_solved_beta'];axes[2].bar(range(len(channels)),[norms[c]['RMS'] for c in channels]);axes[2].set_xticks(range(len(channels)),['chi','Khat','Theta','alpha','Axx','Lambda-x'],rotation=35);axes[2].set(yscale='log',ylabel='Penrose-volume RMS',title='Full physical-source errors still fail')
 fig.suptitle('Global scalar candidate + actual old-FD vector solve: residual converged, science incomplete');fig.savefig(out/'actual-stage-radial-source-comparison.png',dpi=150);plt.close(fig)
summary['inputs_unchanged']=all(sha(Path(p))==h for p,h in summary['input_sha256'].items());assert summary['inputs_unchanged'];(out/'analysis.json').write_text(json.dumps(summary,indent=2,allow_nan=False)+'\n');print(json.dumps({'solve':summary['solve'],'radius_groups':len(profiles),'maximum_angular_scatter':max(row['angular_scatter'] for row in profiles)}))
